namespace RayCraft.Examples.Docs;

public static class WrittenDocs
{
    public static IReadOnlyDictionary<string, string> Common { get; } = new Dictionary<string, string> { ["Class"] = "Extra CSS classes added to the root element.", ["Style"] = "Inline style added to the root element.", ["ChildContent"] = "Content rendered inside the component.", ["HelperText"] = "Hint shown below the field.", ["Placeholder"] = "Placeholder shown when the field is empty.", ["Disabled"] = "Disables interaction.", ["Value"] = "Current value. Use with @bind-Value.", ["ValueChanged"] = "Raised when the value changes.", ["DisplayName"] = "Name used in validation messages.", ["Max"] = "Largest allowed value (ProgressBar: the value that means 100%; Rating: number of stars).", ["Min"] = "Smallest allowed value.", ["Invalid"] = "Marks the field as invalid.", ["ReadOnly"] = "Shows the value but does not allow changes." };

    public static IReadOnlyDictionary<string, string> Leads { get; } = new Dictionary<string, string> { ["Accordion"] = "Expandable sections. By default opening one closes the others; set Multiple to allow several.", ["ActivityFeed"] = "A list of what happened and who did it, newest first, grouped by day, with an icon or the initials of the actor and an optional detail line.", ["AddressField"] = "A recipient field for e-mail: every address becomes a chip. Type or paste a list, pick from suggestions that come from your data source, double-click a chip to edit it, and see at once which addresses are not valid.", ["Alert"] = "Inline message colored by severity, with a matching icon. Set Dismissible to show a close button; use bind-Visible or OnDismiss to react when it is closed.", ["AppBar"] = "Top bar for the title and primary actions. Put links in NavContent and they sit in the bar on wide screens and fold behind a menu button below 768px.", ["Autocomplete"] = "Text field that filters a list while you type. Supports the arrow keys, Enter and Escape and follows the ARIA combobox pattern. The value is always one of the items.", ["AvatarGroup"] = "Overlapping avatars for a team or the people on an item. More than Max people collapse into a +n avatar whose hint lists the names.", ["Avatar"] = "Square user badge: image, initials computed from a name, or a default user icon.", ["Badge"] = "Small status label.", ["Barcode"] = "Draws Code 128 (all printable ASCII, digits are packed in pairs), Code 39 (capitals, digits and - . $ / + % space), EAN-13, EAN-8 and UPC-A (the check digit is added, or verified when given) as plain SVG. ShowDownload adds buttons that save the barcode as SVG or PNG. Always dark on light so scanners read it in both themes.", ["Breadcrumbs"] = "Shows the path to the current page. The last item is the current page.", ["BreakpointObserver"] = "Tells your code which named breakpoint (Xs to Xxl) the window is in and re-renders when it changes. Use CSS classes when styling is enough; use this when the markup itself must differ.", ["BusyOverlay"] = "Wraps a region and, while Busy is true, dims it and shows a spinner on top. The cover blocks the mouse, marks the region with aria-busy and announces the label. DelayMilliseconds (150 by default) keeps fast actions from flashing the spinner. Pair it with FormState when the keyboard must be blocked too.", ["ButtonGroup"] = "Joins buttons into one segmented control, horizontally or vertically. Combine it with ToggleButton for a view switcher.", ["Button"] = "Triggers an action, or navigates when Href is set (the button then renders as a link with the same look). Three variants (Filled, Outlined, Text), six colors, three sizes, and optional icons before or after the label. For a button with only an icon use IconButton. Loading shows a spinner in place of the start icon and blocks clicks (so a double submit cannot happen); BusyWhileClicking does the same automatically for as long as an asynchronous OnClick handler runs.", ["Calendar"] = "Month grid used by DatePicker and DateTimeRangePicker. Use it on its own for inline date selection. It can mark a single value or a range, show one or more months side by side (MonthCount), and follows the current RayCraft language. Keyboard: arrow keys move by day and week, PageUp and PageDown by month (with Shift by year), Home and End to the start and end of the week, Enter picks the day.", ["Captcha"] = "Simple human check with a small arithmetic question. It keeps out basic bots only; verify real protection on the server (for example with a service built for that).", ["Card"] = "Container with optional header and footer.", ["Carousel"] = "Slides with previous and next buttons and indicators. Autoplay is optional; it pauses on hover and focus and has a pause button, as WCAG requires.", ["Cascader"] = "Pick one value from a hierarchy: a column of choices opens a column of sub choices. Arrow keys move, Right opens the next column, Left goes back, Enter chooses.", ["CheckboxGroup"] = "A group of check boxes for choosing several items from a list, inside a fieldset with a legend so screen readers announce the group name. ShowSelectAll adds a Select all box that shows the mixed state when only some items are chosen.", ["Checkbox"] = "Boolean input with a label.", ["Chip"] = "Compact label, optionally removable.", ["ChipSet"] = "Chips that can be selected, for filters and tags. One choice by default, several with Multiple. Selected chips show a check mark.", ["CodeBlock"] = "Shows source code with light syntax coloring (C#, JavaScript, TypeScript, JSON, HTML, SCSS, SQL and shell), optional line numbers and a copy button. Colors come from theme tokens, so contrast holds in both themes.", ["Collapse"] = "Shows or hides its content. Bind Expanded to any button; KeepMounted keeps the content in the page while hidden.", ["ColorButton"] = "A toolbar button for a color: an icon with a bar of the chosen color under it. Clicking it opens the color chooser of the browser.", ["ColorPalette"] = "A grid of color swatches that works as a radio group: one tab stop, the arrow keys, Home and End move and choose. Colors are checked as six digit hex values.", ["ColorPicker"] = "Color field with the native color chooser, a hex text box and optional preset swatches. The value is a string such as #0066CC.", ["CommandContextMenu"] = "A context menu built from MenuCommand data, with submenus, check marks, shortcuts and the same keyboard handling as MenuBar. It opens at the point you give it and is kept inside the window.", ["CommentThread"] = "Comments with replies, a box for a new comment and Reply and Delete commands. Text is shown as typed (line breaks kept, nothing is treated as HTML).", ["Container"] = "Centers content and limits its width. The default width follows the breakpoints (540, 720, 960, 1140 and 1320 px).", ["ContextMenu"] = "Menu opened with the right mouse button or the context menu key over its content. It stays inside the viewport and supports the arrow keys and Escape.", ["CookieConsent"] = "A banner that asks which cookies are allowed. It remembers the answer in local storage, offers Accept all, Only necessary and a choice by category, and does not block the page.", ["CopyButton"] = "Copies a text to the clipboard and confirms it with a check mark. Needs a secure context (https or localhost).", ["Countdown"] = "Counts down to a moment in time and raises OnFinished when it is reached.", ["DatePicker"] = "Date field with a calendar. Month names, weekday names, the first day of the week and the date format (also used as the default placeholder) follow the current RayCraft language. Text that is not a date shows an error even without an EditContext. Opening the calendar moves focus into it, Escape closes it and returns focus to the button.", ["DateTimePicker"] = "One field for date and time: a DatePicker and a TimePicker side by side that together bind a DateTime.", ["DateTimeRangePicker"] = "Period with start and end, picked on one calendar that shows two months side by side (Months) (first click sets the start, second sets the end) and typed or adjusted per field. The value is a DateTimeRange. Set IncludeTime to false for dates only. A date typed without a time keeps the time already chosen. Times use the same field as TimePicker.", ["Descriptions"] = "Key and value pairs in a grid, for details of a record. The columns collapse to one on narrow screens.", ["Dialog"] = "Modal window. Focus moves into it and stays inside until it closes (Escape, the close button or a backdrop click); focus then returns to the previous element. From code, use IRayCraftDialogs.ConfirmAsync / AlertAsync for messages, PromptAsync for a text value (null when cancelled), or ShowAsync<TComponent> to show your own component; it receives a cascading DialogContext whose Close(data) and Cancel() finish the dialog. This needs one DialogHost in your layout.", ["Divider"] = "Thin line separating content, horizontal or vertical.", ["Drawer"] = "Side panel. Temporary drawers float over the page with a backdrop, close with Escape and move focus into the panel; set Temporary=false for a permanent sidebar. With Mini the closed drawer stays as a narrow rail of icons (give NavItems a Tooltip) and opening it shows icons with text.", ["DropDownList"] = "A combobox for very long lists. Only the options in view are drawn, so 100,000 entries open at once; typing narrows the list.", ["DropDownTree"] = "A drop-down field that opens a tree to choose one node. It is built from TreeView and Popover and keeps their keyboard behavior.", ["EmptyState"] = "Message for lists and pages without content, with an icon, an explanation and optional actions.", ["ErrorSummary"] = "Lists every validation message of the surrounding EditForm in one block. Place it inside an EditForm with a validator.", ["EventCalendar"] = "Month view with events. Events spanning several days appear on each day; a day shows up to MaxEventsPerDay and a +n more link. On narrow screens the events become colored dots and the day number opens the day.", ["Fieldset"] = "Groups related form controls under a legend. Disabled turns off every control inside it.", ["FileUpload"] = "Drop zone and file picker. It checks size, type and count, lists the accepted files and raises FilesChanged; reading the content is up to you (IBrowserFile.OpenReadStream).", ["FloatingActionButton"] = "A square button fixed to a corner of the screen for the main action. Extended shows the text next to the icon; the text is always the accessible name.", ["FormBuilder"] = "Builds a form from field definitions: text, email, password, number, date, text area, select, radio, check box and switch. It validates required fields, email format and number limits with localized messages and focuses the first problem.", ["FormLayout"] = "Arranges labels and fields in a responsive twelve-column grid, with titled sections.", ["FormState"] = "Locks every RayCraft field inside it with one parameter: Disabled blocks them completely, ReadOnly shows the values without allowing changes. Use it while a form is being saved or when the user may only view a record. It renders nothing itself.", ["Fullscreen"] = "Adds a button that shows its content full screen. It uses the Fullscreen API and a full-window layer on browsers without it (some phones).", ["Grid"] = "12-column grid. Span sets the width of an item on every screen, and Sm, Md, Lg, Xl and Xxl change it from that breakpoint up (the same breakpoints as the Breakpoints page). Without Span an item takes the full row.", ["Highlighter"] = "Marks every occurrence of a search text inside a string, ignoring case unless CaseSensitive is set.", ["Hotkey"] = "Shortcuts are ignored while typing in a field unless AllowInInputs is set.", ["IconButton"] = "Button that shows only an icon. Label is required: it becomes the accessible name and the tooltip.", ["ImageGallery"] = "Grid of thumbnails that opens a full-screen viewer (Lightbox) with previous and next buttons, the arrow keys and Escape.", ["Image"] = "Image with required alternative text, fit modes, optional border and caption. Lazy loading is on by default.", ["InPlaceEditor"] = "Shows a value as text; a click turns it into a field with save and cancel buttons. Enter saves, Escape cancels; with Lines above one Ctrl+Enter saves.", ["InfiniteScroll"] = "Loads more content when the end of a list comes into view. It uses IntersectionObserver (with a scroll fallback) and raises OnLoadMore; set Loading while you fetch and HasMore to false at the end.", ["Link"] = "Styled anchor. External links open in a new tab with rel=\"noopener noreferrer\" and show an icon.", ["ListBox"] = "Always-visible list for one choice (radio buttons underneath) or several (check boxes). Native inputs keep keyboard and screen reader behavior.", ["List"] = "Vertical list of items with icon, two text lines and a trailing action. Items become links or buttons when Href or OnClick is set.", ["LoginForm"] = "Ready-made sign-in form with localized validation. It raises OnSubmit with the entered LoginModel and leaves the actual sign-in to you.", ["MarkdownEditor"] = "Text area with a formatting toolbar and a live preview, for people who write Markdown instead of rich text. The preview uses the Markdown component, so all text is escaped and only safe links are kept. It works with EditForm like the other inputs.", ["Markdown"] = "Shows Markdown text: headings, emphasis, links, images, lists (nested), quotes, code, tables and rules. All text is HTML-encoded first and only safe link and image addresses are kept, so it is safe for text typed by users.", ["Marquee"] = "Scrolling strip for short announcements. It pauses on hover and focus, has a pause button (WCAG 2.2.2) and stops completely when the system asks for reduced motion.", ["MaskedInput"] = "Text field that formats what you type by a mask: 0 is a digit, a is a letter, * is a letter or digit, any other character is a fixed separator (escape a mask character with a backslash). The fixed part is added for you (typing it yourself is also accepted). The value is only accepted when the mask is complete. Preset gives ready masks with checks (Date, Time, CreditCard with the Luhn check), and Pattern adds a regular expression that the finished value must match.", ["Mention"] = "A text box that suggests names after a trigger character (@ by default). Arrow keys and Enter choose; the chosen name is inserted with the trigger.", ["MenuBar"] = "A horizontal menu bar for applications: top-level menus with commands, shortcuts, check marks, icons and submenus. Hovering switches between open menus and the arrow keys move through them.", ["Menu"] = "Button that opens a list of actions. Closes on selection, Escape or a click outside.", ["MoneyField"] = "Amount field for decimal and decimal? values. The text is formatted and parsed with the current culture (both 1,234.50 and 1.234,50 are understood), rounded to Decimals and kept inside Min and Max. The currency symbol sits on the side the culture uses.", ["MonthPicker"] = "Chooses a month and year. The value is the first day of the month. Typing, errors and focus behave as in DatePicker.", ["MultiColumnComboBox"] = "An Autocomplete whose list shows several columns with a header row. Typing searches all columns.", ["MultiSelect"] = "Dropdown with check boxes for choosing several items. The trigger summarizes the selection; Select all and Clear are built in.", ["NavMenu"] = "Vertical navigation with active-page highlighting (built on NavLink) and collapsible groups. Give NavItem a Tooltip and NavGroup an Icon when the menu is used in a Drawer with Mini: the closed drawer then shows only icons, and a group opens as a small flyout.", ["NotificationCenter"] = "A bell button with a count of unread notifications and a panel that lists them. People can read, dismiss and clear them; the count is announced to screen readers.", ["NumericField"] = "Number input for any numeric type (int, decimal, double, nullable versions). Values outside Min and Max are clamped, and the buttons step by Step.", ["OtpInput"] = "One box per character for verification codes. Typing moves to the next box, Backspace to the previous one, and a pasted code fills all boxes.", ["Overlay"] = "Dims the page (or, with Absolute, its positioned parent) and can show content such as a spinner. DismissOnClick closes it on a click.", ["Pagination"] = "Page selector with ellipsis for long ranges.", ["Panel"] = "Titled section with an optional collapse button and header actions.", ["PasswordStrength"] = "Shows how strong a password is with four bars, a word and a list of the rules it meets. The level is also read out for screen readers.", ["PercentField"] = "Number field that the user types as a percentage (12.5) while the value is stored as a fraction (0.125). Min and Max are in percent (0 to 100 by default); Decimals sets how many digits are kept.", ["Popover"] = "Floating panel opened by an activator. Closes with Escape or a click outside.", ["PricingTable"] = "Plan cards with a price, a feature list and a button, with an optional switch between monthly and yearly billing. Included features carry a check and a text for screen readers.", ["ProfileMenu"] = "Avatar, name and a menu for the signed-in user, built from the same MenuItem elements as Menu.", ["ProgressBar"] = "Shows progress from 0 to Max. Without a Value it is indeterminate.", ["ProgressButton"] = "A button that shows work in progress: a spinner while Progress is not set, a bar along the bottom edge and a spoken percentage when it is.", ["ProgressCircular"] = "Ring that shows a determinate progress value. For unknown durations use Spinner.", ["PropertyGrid"] = "Edits the public properties of any object, grouped by Category and labeled with DisplayName. Text, numbers, booleans, enums and dates get matching editors; read-only properties stay read-only.", ["QrCode"] = "Draws a QR code as plain SVG, with no image service or script. Text up to 2331 bytes (all 40 versions, error correction level M). The code is always dark on light so scanners read it in both themes.", ["RadioGroup"] = "One choice from a short list. Use Items for simple lists or Radio children for custom labels. Arrow keys move the selection, as with native radio buttons.", ["RangeSelector"] = "A strip with two handles that selects an interval of a series; a small preview of the data sits behind the handles.", ["RangeSlider"] = "Slider with two thumbs for choosing a lower and an upper value. Both thumbs are native range inputs, so the arrow keys work.", ["RatingDisplay"] = "Read-only stars with fractions (4.5 shows four and a half), an optional number and a review count. Use Rating when people should choose a value.", ["Rating"] = "Star rating. Click the current star again to clear it. Arrow keys change the value.", ["RegisterForm"] = "Ready-made registration form: name, email, password and confirmation, with localized validation.", ["Repeater"] = "Shows a list of items with your own template. It adds what a plain loop lacks: a header, an empty state, a grid with a set number of columns and optional paging (PageSize).", ["ResultPage"] = "A full page message for an outcome: success, error, information, warning, page not found, no access and server error, with an icon, a title, a text and buttons.", ["ScrollSpy"] = "An in-page contents list that highlights the heading currently at the top of the screen. It finds the headings with a CSS selector (headings need an id), marks the current link with aria-current and links with plain fragments, so it works without scripts too. Call RefreshAsync after the headings change.", ["ScrollToTop"] = "Floating button that appears after scrolling down and returns to the top of the page. It needs no round trip to the server.", ["SearchBox"] = "Search field with an icon and a clear button. OnSearch runs on Enter, on the clear button and (optionally) on every keystroke; Escape clears the text.", ["Select"] = "Drop-down for choosing one item. TValue can be any type, including your own records.", ["SignaturePad"] = "Canvas for drawing a signature with a mouse, finger or pen. The value is a PNG as a data URL. Drawing is not keyboard accessible, so also offer an alternative such as typing the name.", ["Skeleton"] = "Placeholder shown while content loads.", ["SkeletonPreset"] = "Ready-made loading placeholders: card, list, table, profile and paragraph. They announce a busy state to screen readers.", ["Slider"] = "Drag to choose a number in a range.", ["Sortable"] = "List that can be reordered by dragging, or with the move buttons for keyboard and touch use. Changes are announced to screen readers.", ["Spacer"] = "Empty element that grows to fill the free space in a flex row, pushing the items after it to the end.", ["SpeedDial"] = "A floating button that opens a short list of actions. Escape closes the list; each action is a real button in the tab order.", ["Spinner"] = "Indeterminate loading indicator with a localized accessible name.", ["SplitButton"] = "A main action with a menu of related actions. The same MenuItem elements as Menu are used.", ["Splitter"] = "Two resizable panes. Drag the bar with the mouse or touch, or focus it and use the arrow keys (Shift for bigger steps, Home and End for the limits). With PersistKey the position is remembered in local storage.", ["Stack"] = "Lays children out in a row or column with a consistent gap.", ["Statistic"] = "Trend colors follow the meaning of the change: LowerIsBetter flips them for costs and errors.", ["Stepper"] = "Guides the user through a sequence of steps with Back and Next buttons.", ["Switch"] = "Boolean toggle, announced to assistive technology as a switch.", ["Table"] = "Simple styled HTML table for static data.", ["Tabs"] = "Switches between panels. Supports the arrow keys, Home and End.", ["TagCloud"] = "Words in sizes that follow their weight. Tags can be links, buttons that select, or plain text.", ["TagInput"] = "Free-form list of tags. Enter or a comma adds the typed text, Backspace in an empty field removes the last tag, and each tag has a remove button.", ["TextContextMenu"] = "The right-click menu of an editable text element: undo, redo, cut, copy, paste and select all, plus commands you add. The editors of RayCraft use it, and it is the way to give your own editor, such as a rich text editor, the same menu.", ["TextField"] = "Single-line text input. Works with EditForm and DataAnnotations; the error message appears below the field.", ["ThemeMenu"] = "One drop-down for the theme and the density: Slate, Slate Dark, Desktop, Desktop Dark, Mist, Mist Dark, Dark and Light, each in the normal and the compact density. The button shows the current choice and the menu marks it with a check. Both settings are saved in localStorage like ThemeToggle and DensityToggle.", ["ThemeToggle"] = "Ready-made switches for the Light, Dark, Slate and Slate Dark themes (ThemeToggle goes through them one by one), the comfortable/compact density (DensityToggle) and the en-US/bg-BG language (LanguageToggle). All persist the choice in localStorage.", ["TimeField"] = "The bare time text box that TimePicker, TimeRangePicker and DateTimeRangePicker are built on. Use it when you need your own label and layout. It shows the time in the format of the current language, accepts typed times and moves by the step with the arrow keys.", ["TimePicker"] = "Time field written in the format of the current RayCraft language (9:30 AM in English, 9:30 in Bulgarian), so it looks the same in every browser. Type a time such as 3:45 pm, or use the arrow keys (by the step) and PageUp and PageDown (by an hour). Text that is not a time shows an error.", ["TimeRangePicker"] = "Start and end time in one field, each written in the format of the current language like TimePicker. The value is a TimeRange. The end must not be before the start unless AllowOvernight is set.", ["TimeSpanPicker"] = "Enters a duration as days, hours, minutes and seconds. The value is a TimeSpan.", ["Timeline"] = "Vertical sequence of events with a marker, time and optional severity color.", ["TitleIndex"] = "A list grouped by first letter with a letter bar on top. A letter moves the focus (and the view) to its section; letters without items are disabled.", ["ToggleButton"] = "Button that keeps an on/off state and exposes it with aria-pressed.", ["ToggleGroup"] = "Segmented control for one choice (radio group) or several (toggle buttons). Use it for view switchers and formatting toggles.", ["Toolbar"] = "Row of tool buttons with role=toolbar.", ["Tooltip"] = "Short hint shown on hover and on keyboard focus. Pure CSS, so it also works before the page becomes interactive.", ["Tour"] = "Step-by-step introduction that highlights page elements chosen by CSS selector. Steps without a matching element appear in the center.", ["TransferList"] = "Two lists with buttons for moving items between them, for choosing a subset from a long list. The chosen items keep the order of the source list.", ["TreeView"] = "Hierarchical list following the ARIA tree pattern. Arrow keys move and expand, Home and End jump, Enter or Space selects. Children come from ChildrenSelector, so any recursive type works, or from an asynchronous ChildrenLoader that runs when a node is first opened.", ["Typography"] = "Headings, body text, captions and overlines with the theme font and sizes. Headings render real h1 to h6 elements.", ["VirtualList"] = "A scrolling list that draws only the rows in view, for hundreds of thousands of items. Rows have a fixed height (a row template can have several lines); the keyboard reaches every row. Rows can come from the server in windows, several rows can be selected and dragged onto a TreeView.", ["WeekPicker"] = "Chooses a whole week. The value is the first day of the week of the current language; the field shows the ISO week number and the dates.", ["Wizard"] = "A guided flow in steps. Each step can validate before the user moves on, a step can be optional, finished steps can be reopened, and the result can show a page of its own.", ["YearPicker"] = "Chooses a year from a grid of twelve years with buttons for earlier and later pages. The value is an int. Typing, errors and focus behave as in DatePicker." };

